description:
Decide what a supervisor does when a worker exits (lesson 6.02). Times are in seconds.

```cpp
struct Decision { bool restart; std::uint64_t at; std::string reason; };

class RestartPolicy
{
public:
    void started(std::uint64_t now);
    Decision exited(std::uint32_t exitCode, std::uint64_t now);
    bool gaveUp() const;
};
```

- **started** records that the worker (re)started at `now`.
- **exited** decides:
  - exit code 0: no restart, reason `finished`.
  - Otherwise it is a failure. Remember the time of the failure. If there have been **5 failures within the last 600 seconds** (counting this one, times `now - 600` to `now` inclusive), give up: no restart, reason `crash loop`, and `gaveUp` stays true; any later exit is also answered with `crash loop`.
  - If the worker had run for **300 seconds or more** since its last start, the delay resets to 1 second.
  - Otherwise the delay is 1 second for the first failure and doubles with each failure in a row, up to 60 seconds.
  - Restart at `now + delay`, reason `restart in Ns`.

starter.solution.cpp:
#include <cstdint>
#include <string>

struct Decision { bool restart; std::uint64_t at; std::string reason; };

class RestartPolicy
{
public:
    void started(std::uint64_t now) {}
    Decision exited(std::uint32_t exitCode, std::uint64_t now) { return { true, now, "restart in 0s" }; }
    bool gaveUp() const { return false; }
};

solution.solution.cpp:
#include <algorithm>
#include <cstdint>
#include <deque>
#include <string>

struct Decision { bool restart; std::uint64_t at; std::string reason; };

class RestartPolicy
{
public:
    void started(std::uint64_t now) { startedAt = now; }

    Decision exited(std::uint32_t exitCode, std::uint64_t now)
    {
        if (stopped) return { false, now, "crash loop" };
        if (exitCode == 0) return { false, now, "finished" };
        failures.push_back(now);
        while (!failures.empty() && failures.front() + 600 < now) failures.pop_front();
        if (failures.size() >= 5) { stopped = true; return { false, now, "crash loop" }; }
        if (now - startedAt >= 300) delay = 1;
        else delay = delay == 0 ? 1 : std::min<std::uint64_t>(delay * 2, 60);
        return { true, now + delay, "restart in " + std::to_string(delay) + "s" };
    }

    bool gaveUp() const { return stopped; }

private:
    std::uint64_t startedAt{ 0 };
    std::uint64_t delay{ 0 };
    std::deque<std::uint64_t> failures;
    bool stopped{ false };
};

unitTests:
TEST("clean exits are not restarted") {
    RestartPolicy p;
    p.started(0);
    const Decision d{ p.exited(0, 50) };
    CHECK(!d.restart);
    CHECK_EQ(d.reason, std::string("finished"));
}
TEST("backoff doubles, then resets after a long run") {
    RestartPolicy p;
    p.started(0);
    Decision d{ p.exited(1, 10) };
    CHECK(d.restart); CHECK_EQ(d.at, 11ull); CHECK_EQ(d.reason, std::string("restart in 1s"));
    p.started(11);
    d = p.exited(1, 12);
    CHECK_EQ(d.reason, std::string("restart in 2s"));
    p.started(14);
    d = p.exited(0xC0000005u, 15);
    CHECK_EQ(d.reason, std::string("restart in 4s"));
    p.started(19);
    d = p.exited(1, 19 + 400);
    CHECK_EQ(d.reason, std::string("restart in 1s"));
}
TEST("the delay stops at 60 seconds") {
    RestartPolicy p;
    std::uint64_t t{ 0 };
    std::string last;
    for (int i{ 0 }; i < 8; ++i)
    {
        p.started(t);
        const Decision d{ p.exited(1, t + 1) };
        last = d.reason;
        t += 1000;
    }
    CHECK_EQ(last, std::string("restart in 60s"));
    RestartPolicy q;
    std::uint64_t now{ 0 };
    std::vector<std::string> reasons;
    for (int i{ 0 }; i < 4; ++i) { q.started(now); reasons.push_back(q.exited(1, now + 1).reason); now += 200; }
    CHECK_EQ(reasons, (std::vector<std::string>{ "restart in 1s", "restart in 2s", "restart in 4s", "restart in 8s" }));
}
TEST("giving up on a crash loop") {
    RestartPolicy p;
    std::uint64_t now{ 0 };
    for (int i{ 0 }; i < 4; ++i) { p.started(now); CHECK(p.exited(1, now + 1).restart); now += 100; }
    p.started(now);
    const Decision d{ p.exited(1, now + 1) };
    CHECK(!d.restart);
    CHECK_EQ(d.reason, std::string("crash loop"));
    CHECK(p.gaveUp());
    CHECK_EQ(p.exited(0, now + 5).reason, std::string("crash loop"));
}

